/* API-backed commerce screens. The standalone ?demo=1 prototype remains separate. */
window.installCommerceUI=({state,api,adoptSession,loadOrders,refreshCatalog,loadAdmin,notice,ensureProducts})=>{
  Object.assign(state,{profile:null,addresses:[],notifications:[],tickets:[],accountTab:'orders',sellerData:null,shoppingRevision:0,shoppingReady:false,shoppingConflict:false});
  let extrasUI=null;
  const empty=()=>({cart:{},wish:[],saved:[],compare:[]});
  const snapshot=()=>structuredClone({cart:db.cart,wish:db.wish,saved:db.saved,compare:db.compare});
  const localKey=id=>'salesync-shopping:'+ (id||'guest');
  const labels={awaiting_gateway:'Awaiting payment availability',pending_payment:'Awaiting test payment',paid:'Test payment confirmed',processing:'Processing',packed:'Packed',shipped:'Shipped',out_for_delivery:'Out for delivery',delivered:'Delivered',cancelled:'Cancelled',payment_failed:'Test payment failed',payment_expired:'Test payment expired',refunded:'Test payment refunded'};
  const stageNext={paid:'processing',processing:'packed',packed:'shipped',shipped:'out_for_delivery',out_for_delivery:'delivered'};
  const previousLogin=login,previousHome=home,previousStore=storeFront;
  login=()=>previousLogin().replace('</form>','</form><p><button class="api-link" data-page="forgot-password">Forgot your password?</button></p>');
  home=()=>previousHome().replace('Payment through PayMongo at checkout',state.catalog?.payment.mode==='local-test'?'Local test payments · no real charges':'Online payment currently unavailable').replace('One secure checkout flow','Clear checkout steps');
  storeFront=()=>previousStore().replace('PayMongo checkout',state.catalog?.payment.mode==='local-test'?'Local test checkout':'Order requests');
  let fieldNumber=0;
  let shoppingQueue=Promise.resolve();
  const initialGuest=snapshot();
  try{if(!localStorage.getItem(localKey()))localStorage.setItem(localKey(),JSON.stringify(initialGuest));}catch{}
  function localShopping(id){try{return {...empty(),...JSON.parse(localStorage.getItem(localKey(id))||'{}')};}catch{return empty();}}
  function applyShopping(data){for(const key of ['cart','wish','saved','compare'])db[key]=structuredClone(data[key]??empty()[key]);}
  function mergeShopping(remote,guest){const result={...remote,cart:{...remote.cart}};for(const [id,qty] of Object.entries(guest.cart||{})){const p=product(id);if(p?.published)result.cart[id]=Math.min(99,Math.max(result.cart[id]||0,qty));}for(const key of ['wish','saved','compare'])result[key]=[...new Set([...(remote[key]||[]),...(guest[key]||[])])].filter(id=>product(id)).slice(0,key==='compare'?4:200);return result;}
  applyShopping(localShopping());
  function persist(){
    const data=snapshot(),id=state.user?.role==='customer'?state.user.id:null;
    try{localStorage.setItem(localKey(id),JSON.stringify(data));}catch{throw Error('Your browser could not save shopping changes.');}
    if(!id||!state.shoppingReady||state.shoppingConflict)return;
    shoppingQueue=shoppingQueue.then(async()=>{
      if(state.user?.id!==id||state.shoppingConflict)return;
      try{const result=await api('/account/shopping',{method:'PUT',body:{ownerId:id,revision:state.shoppingRevision,shopping:data}});if(state.user?.id===id){state.shoppingRevision=result.revision;if(JSON.stringify(snapshot())===JSON.stringify(data)){applyShopping(result.shopping);try{localStorage.setItem(localKey(id),JSON.stringify(result.shopping));}catch{}}}}
      catch(error){if(state.user?.id===id){state.shoppingConflict=true;notify(error.code==='REVISION_CONFLICT'?'Shopping changed in another tab or device. Refresh before making more changes.':'Shopping is saved in this browser; server synchronization failed. Refresh to retry.');}}
    });
    return shoppingQueue;
  }
  async function loadCustomer(mergeGuest=false){
    if(state.user?.role!=='customer')return;
    await shoppingQueue;
    const id=state.user.id,guest=localShopping();
    try{const pending=JSON.parse(sessionStorage.getItem('salesync-buy-now')||'null');if(pending?.ownerId===id)await ensureProducts(pending.items.map(line=>line.id));}catch{}
    const [profile,addresses,notifications,tickets,saved]=await Promise.all([api('/account'),api('/account/addresses'),api('/account/notifications'),api('/account/support'),api('/account/shopping')]);
    if(state.user?.id!==id)return;
    state.profile=profile.profile;state.addresses=addresses.addresses;state.notifications=notifications.notifications;state.tickets=tickets.tickets;state.shoppingRevision=saved.revision;state.shoppingReady=true;state.shoppingConflict=false;
    await ensureProducts([saved.shopping,guest,localShopping(id),initialGuest].flatMap(value=>[...Object.keys(value.cart||{}),...(value.wish||[]),...(value.saved||[]),...(value.compare||[])]));
    let data=saved.shopping;
    if(mergeGuest)data=mergeShopping(data,guest);
    else if(saved.revision===0)data=mergeShopping(data,localShopping(id));
    // Preserve the pre-upgrade browser cart once for the currently authenticated customer.
    if(saved.revision===0&&localStorage.getItem('salesync-api-shopping-v1')){data=mergeShopping(data,initialGuest);try{localStorage.removeItem('salesync-api-shopping-v1');}catch{}}
    applyShopping(data);
    try{localStorage.setItem(localKey(id),JSON.stringify(data));}catch{}
    if(JSON.stringify(data)!==JSON.stringify(saved.shopping)){persist();await shoppingQueue;}
    if(mergeGuest)try{localStorage.setItem(localKey(),JSON.stringify(empty()));}catch{}
    if(!ui.shipping.address){const address=state.addresses.find(a=>a.default);if(address)ui.shipping={...address};else ui.shipping={name:state.user.name,phone:state.profile.phone};}
  }
  function afterLogout(){extrasUI?.reset();state.reportFilters={};state.customerFilters='';state.profile=null;state.addresses=[];state.notifications=[];state.tickets=[];state.sellerData=null;state.shoppingReady=false;state.shoppingRevision=0;state.shoppingConflict=false;state.accountTab='orders';state.buyNowItems=null;try{sessionStorage.removeItem('salesync-buy-now');}catch{}state.checkoutDone=null;state.checkoutKey=null;state.checkoutSignature=null;ui.paymentOrderId=null;ui.shipping={};applyShopping(localShopping());}
  function badge(status){return `<span class="pill ${['paid','delivered','approved'].includes(status)?'good':['cancelled','payment_failed','payment_expired','rejected','refunded','suspended'].includes(status)?'bad':'warn'}">${e(labels[status]||status.replaceAll('_',' '))}</span>`;}
  const action=(label,attribute,value='',extra='')=>`<button class="btn mini ghost" data-commerce-${attribute}="${e(value)}" ${extra}>${e(label)}</button>`;
  const input=(name,label,value='',type='text',extra='')=>{const id='commerce-'+name+'-'+(++fieldNumber);return `<div class="field"><label for="${id}">${e(label)}</label><input id="${id}" name="${e(name)}" type="${type}" value="${e(value)}" ${extra}></div>`;};
  function orderCards(orders){return orders.length?orders.map(order=>`<article class="surface block commerce-order" data-feature-order-id="${e(order.id)}"><div class="toolbar"><div><b>${e(order.id)}</b><div class="small subtle">${e(new Date(order.createdAt).toLocaleString())}</div></div>${badge(order.status)}</div>${order.payment?.mode==='local-test'?'<p class="commerce-test-label">LOCAL TEST · No real money charged</p>':''}${order.lines.map(line=>`<div class="lineitem"><span>${e(line.name)} × ${line.qty}</span><b>${fmt(line.price*line.qty)}</b></div>`).join('')}<div class="flex between wraptext"><b>Total: ${fmt(order.total)}</b><div class="api-tab-actions">${order.status==='pending_payment'?action('Continue test payment','pay-order',order.id):''}${['pending_payment','awaiting_gateway'].includes(order.status)?action('Cancel unpaid order','cancel-order',order.id):''}${order.status==='delivered'&&!order.returnRequest?action('Request return','return-order',order.id):''}</div></div>${order.inventoryReserved?`<p class="small subtle">Stock reserved until ${e(new Date(order.expiresAt).toLocaleTimeString())}.</p>`:order.status==='awaiting_gateway'?'<p class="small subtle">No payment collected. Inventory is not reserved.</p>':''}${order.shipments?.length?`<div class="commerce-shipments">${order.shipments.map(sh=>`<div><b>${e(sh.seller)}</b> · ${e(labels[sh.status]||sh.status)}${sh.tracking?`<div class="small subtle">${e(sh.courier)} · Tracking: ${e(sh.tracking)}</div>`:''}</div>`).join('')}</div>`:''}${order.returnRequest?`<p class="notice">Return request: ${e(order.returnRequest.status)}</p>`:''}${order.history?.length?`<details class="api-history"><summary>Order history</summary>${order.history.map(item=>`<div class="api-diff">${e(item.note)}<br><span class="subtle">${e(new Date(item.createdAt).toLocaleString())}</span></div>`).join('')}</details>`:''}</article>`).join(''):'<div class="api-empty"><h3>No orders yet</h3><p>Find something you love and add it to your cart.</p><button class="btn primary" data-page="shop">Browse products</button></div>';}
  function addressForm(address={}){return `<form id="apiCommerceAddressForm" class="api-form"><input type="hidden" name="id" value="${e(address.id||'')}"><input type="hidden" name="revision" value="${address.revision||0}"><div class="grid2">${[['name','Recipient name'],['phone','Philippine mobile'],['address','House / street / building'],['barangay','Barangay'],['city','City / municipality'],['province','Province'],['postal','Postal code']].map(([key,label])=>input(key,label,address[key]||'',key==='phone'?'tel':'text',`required ${key==='phone'?'pattern="09[0-9]{9}"':key==='postal'?'pattern="[0-9]{4}"':'minlength="2"'} maxlength="160"`)).join('')}</div><label class="commerce-check"><input type="checkbox" name="default" ${address.default?'checked':''}> Default delivery address</label><button class="btn primary">Save address</button></form>`;}
  function ticketsView(tickets,admin=false){return `<div class="stack">${tickets.map(ticket=>`<article class="surface block"><div class="toolbar"><h3>${e(ticket.subject)}</h3>${badge(ticket.status)}</div>${ticket.messages.map(message=>`<div class="commerce-message"><b>${e(message.name)} <span class="subtle small">${e(message.role)}</span></b><p>${e(message.message)}</p></div>`).join('')}<form id="apiCommerceReply-${e(ticket.id)}" class="api-form"><input type="hidden" name="id" value="${e(ticket.id)}"><input type="hidden" name="revision" value="${ticket.revision}"><input type="hidden" name="scope" value="${admin?'admin':'account'}"><div class="field"><label>Reply</label><textarea name="message" required minlength="2" maxlength="2000" rows="3"></textarea></div><label class="commerce-check"><input type="checkbox" name="closed" ${ticket.status==='closed'?'checked':''}> Close this request</label><button class="btn ghost">Send reply</button></form></article>`).join('')||'<div class="api-empty"><h3>No support requests</h3><p>Support conversations will appear here.</p></div>'}</div>`;}
  function accountContent(){
    const profile=state.profile||state.user;
    if(state.accountTab==='profile')return `<h2>Profile & security</h2><form id="apiCommerceProfileForm" class="api-form">${input('name','Full name',profile.name,'text','required minlength="2" maxlength="80"')}${input('phone','Philippine mobile (optional)',profile.phone||'','tel','pattern="09[0-9]{9}"')}<p class="small subtle">Verified email: ${e(state.user.email)}</p><button class="btn primary">Save profile</button></form><hr><h3>Change password</h3><form id="apiCommercePasswordForm" class="api-form">${input('currentPassword','Current password','','password','required autocomplete="current-password" maxlength="128"')}${input('password','New password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button class="btn ghost">Change password and sign out</button></form>`;
    if(state.accountTab==='addresses')return `<div class="toolbar"><h2>Saved addresses</h2>${action('Add address','address','new')}</div>${state.addresses.map(address=>`<article class="commerce-address"><b>${e(address.name)}</b> ${address.default?'<span class="pill good">Default</span>':''}<p>${e(address.address)}, ${e(address.barangay)}, ${e(address.city)}, ${e(address.province)} ${e(address.postal)}<br>${e(address.phone)}</p><div class="api-tab-actions">${action('Edit','address',address.id)}${action('Remove','delete-address',address.id)}</div></article>`).join('')||'<div class="api-empty"><h3>No saved addresses</h3><p>Add a delivery address to reuse at checkout.</p></div>'}`;
    if(state.accountTab==='saved')return `<h2>Wishlist & saved products</h2>${wishlistInner()}${savedSection()}`;
    if(state.accountTab==='notifications')return `<div class="toolbar"><h2>Notifications</h2>${action('Mark all read','read-notifications')}</div>${state.notifications.map(item=>`<div class="lineitem"><div>${!item.readAt?'<span class="pill good">New</span> ':''}${e(item.message)}<div class="small subtle">${e(new Date(item.createdAt).toLocaleString())}</div></div></div>`).join('')||'<div class="api-empty"><h3>No notifications yet</h3><p>Order and support updates will appear here.</p></div>'}`;
    if(state.accountTab==='support')return `<h2>Help requests</h2><form id="apiCommerceSupportForm" class="api-form">${input('subject','Subject','','text','required minlength="3" maxlength="120"')}<div class="field"><label for="support-message">How can we help?</label><textarea id="support-message" name="message" required minlength="10" maxlength="2000" rows="4"></textarea></div><button class="btn primary">Send request</button></form><hr>${ticketsView(state.tickets)}`;
    if(state.accountTab==='seller')return sellerOverview();
    return `<div class="toolbar"><h2>My orders</h2><button class="btn mini ghost" data-api-refresh-orders>Refresh</button></div>${extrasUI?extrasUI.customerOrders(orderCards(state.orders)):orderCards(state.orders)}`;
  }
  function sellerOverview(){const store=state.profile?.store;return store?`<h2>Your seller store</h2><h3>${e(store.name)}</h3>${badge(store.status)}<p>${e(store.description)}</p>${store.status==='approved'?action('Open seller workspace','seller-open'):'<p class="notice">Management reviews seller applications before products can be published. Your customer account remains available.</p>'}`:`<h2>Apply to sell</h2><p class="subtle">Create your store profile. Management must approve it before you can publish products.</p><form id="apiCommerceSellerApplication" class="api-form">${input('name','Store name','','text','required minlength="2" maxlength="60"')}${input('tagline','Store tagline','','text','required minlength="2" maxlength="140"')}<div class="field"><label for="store-description">Description</label><textarea id="store-description" name="description" required minlength="10" maxlength="1000" rows="4"></textarea></div><button class="btn primary">Submit seller application</button></form>`;}
  account=()=>`<div class="wrap page"><div class="section-head" style="margin-top:0"><div><h1>My account</h1><p>Welcome back, ${e(state.user?.name)}.</p></div><button class="btn ghost" data-api-logout>Sign out</button></div>${state.message?`<div class="api-status ${state.error?'error':'success'}" role="${state.error?'alert':'status'}">${e(state.message)}</div>`:''}<div class="side-layout commerce-account"><aside class="surface appnav"><div class="role-title">${e(state.user?.name)}</div><p class="commerce-account-email">${e(state.user?.email)}</p>${[['orders','Orders & tracking'],['profile','Profile & security'],['addresses','Saved addresses'],['saved','Wishlist & saved'],['notifications','Notifications'],['support','Help requests'],['seller',state.profile?.store?'Your seller store':'Apply to sell']].map(([key,label])=>`<button class="${state.accountTab===key?'active':''}" data-commerce-tab="${key}">${e(label)}</button>`).join('')}</aside><section class="surface section-box api-order-list">${accountContent()}</section></div></div>`;
  function paymentView(order){if(order.payment?.mode==='paymongo-test')return `<div class="wrap page"><section class="surface section-box api-auth"><span class="pill warn">PayMongo TEST ONLY - no real money</span><h1>${order.status==='pending_payment'?'Complete PayMongo test checkout':e(labels[order.status]||order.status)}</h1><p>Reference: ${e(order.id)}</p><p>Total: <b>${fmt(order.total)}</b></p><p>Returning from PayMongo does not confirm payment. Check status for provider verification. Stock remains reserved while a payment is processing.</p>${state.message?`<div class="api-status ${state.error?'error':'success'}" role="status">${e(state.message)}</div>`:''}${order.lines.map(l=>`<p>${e(l.name)} / ${e(l.sku)} × ${l.qty}</p>`).join('')}${order.status==='pending_payment'?`<div class="stack">${action('Continue to PayMongo TEST','hosted',order.id,'data-operation="checkout"')}${action('Check payment status','hosted',order.id,'data-operation="refresh"')}${action('Cancel test checkout','hosted',order.id,'data-operation="cancel"')}</div>`:''}<button class="btn ghost" data-page="account">View my orders</button></section></div>`;return `<div class="wrap page"><section class="surface section-box commerce-payment"><span class="commerce-test-label">${order.payment?'LOCAL TEST CHECKOUT · NO REAL MONEY':'UNPAID ORDER REQUEST'}</span><h1>${order.status==='pending_payment'?'Complete your test payment':order.status==='awaiting_gateway'?'Order request saved':e(labels[order.status]||order.status)}</h1>${state.message?`<div class="api-status ${state.error?'error':'success'}" role="${state.error?'alert':'status'}">${e(state.message)}</div>`:''}<p>Reference: <b>${e(order.id)}</b></p>${order.payment?'<p class="notice">This is a localhost payment simulator. It does not connect to PayMongo, ask for card details, or charge money.</p>':'<p>Online payment is currently unavailable. No payment was collected and stock is not reserved.</p>'}${order.lines.map(line=>`<div class="lineitem"><span>${e(line.name)} × ${line.qty}</span><b>${fmt(line.price*line.qty)}</b></div>`).join('')}<div class="lineitem flex between"><span>Total</span><b>${fmt(order.total)}</b></div>${order.status==='pending_payment'?`<p class="small subtle">Stock is reserved until ${e(new Date(order.expiresAt).toLocaleString())}. Choose a test outcome:</p><div class="stack"><button class="btn primary" data-commerce-payment="${e(order.payment.id)}" data-outcome="success">Simulate successful payment</button><div class="api-tab-actions">${['failed','expired','cancelled'].map(outcome=>`<button class="btn ghost" data-commerce-payment="${e(order.payment.id)}" data-outcome="${outcome}">Simulate ${outcome}</button>`).join('')}</div></div>`:''}<div class="api-tab-actions" style="margin-top:20px"><button class="btn ghost" data-page="account">View my orders</button><button class="btn ghost" data-page="shop">Continue shopping</button></div></section></div>`;}
  function savedAddressSelect(){return state.addresses.length?`<div class="field commerce-saved-address"><label for="commerce-delivery-address">Use a saved address</label><select id="commerce-delivery-address" data-commerce-delivery><option value="">Enter another address</option>${state.addresses.map(address=>`<option value="${e(address.id)}">${e(address.name+' · '+address.address)}</option>`).join('')}</select></div>`:'';}
  function productForm(productValue,scope){
    const p=productValue||{name:'',description:'',sku:'',category:'Electronics',price:'',was:'',primary:0,published:true,photo:'',spec:{}},stores=scope==='seller'?[state.sellerData.store]:state.adminData.catalog.stores;
    return `<form id="apiCommerceProductForm" class="api-form"><input type="hidden" name="scope" value="${scope}"><input type="hidden" name="id" value="${e(p.id||'')}"><input type="hidden" name="revision" value="${p.revision||0}"><div class="grid2">${input('name','Product name',p.name,'text','required minlength="2" maxlength="120"')}${input('sku','SKU',p.sku,'text','required minlength="2" maxlength="64"')}<div class="field"><label for="commerce-category">Category</label><select id="commerce-category" name="category">${CATS.map(category=>`<option ${p.category===category?'selected':''}>${e(category)}</option>`).join('')}</select></div><div class="field"><label for="commerce-store">Seller store</label><select id="commerce-store" name="storeId" ${p.id?'disabled':''}>${stores.map(store=>`<option value="${e(store.id)}" ${p.storeId===store.id?'selected':''}>${e(store.name)}</option>`).join('')}</select></div>${input('price','Price (PHP)',p.price,'number','required min="0.01" step="0.01"')}${input('was','Original price (PHP)',p.was,'number','required min="0.01" step="0.01"')}${input('primary','Stock on hand',p.unallocatedOnHand??p.onHand??p.primary,'number',`${p.variationGroups?.length?'readonly':''} required min="0" max="1000000" step="1"`)}${input('reason','Stock or moderation reason','','text','maxlength="200" placeholder="Required when changing stock"')}</div><p class="small subtle">${p.reserved||0} units reserved. Stock cannot be reduced below active reservations.</p><div class="field"><label for="commerce-description">Description</label><textarea id="commerce-description" name="description" maxlength="2000" rows="3">${e(p.description)}</textarea></div><div class="field"><label for="commerce-spec">Specifications (one “Name: Value” per line)</label><textarea id="commerce-spec" name="spec" rows="3">${e(Object.entries(p.spec||{}).map(([key,value])=>key+': '+value).join('\n'))}</textarea></div>${input('photo','Image URL or uploaded image',p.photo||'','text','maxlength="1000"')}<div class="field"><label for="commerce-image">Upload PNG, JPEG or WebP (up to 750 KB)</label><input id="commerce-image" name="image" type="file" accept="image/png,image/jpeg,image/webp"></div><label class="commerce-check"><input name="published" type="checkbox" ${p.published?'checked':''}> Published</label><button class="btn primary full">${p.id?'Save product':'Create product'}</button>${p.id?`<button type="button" class="btn ghost" data-variant-manage="${e(p.id)}" data-scope="${scope}">Manage variations</button>`:'<p class="small">Save this product before configuring variations.</p>'}</form>`;
  }
  function openProduct(p,scope='admin'){openOverlay(p?'Edit catalog & inventory':'Create product',productForm(p,scope),true);}
  function catalogView(data,scope='admin'){return `<section class="surface section-box"><div class="toolbar"><div><h2>Catalog & inventory</h2><p class="small subtle">Stock on hand, reservations and availability are tracked separately.</p></div><button class="btn primary" data-commerce-new-product="${scope}">Create product</button></div><div class="table-wrap"><table><thead><tr>${['Product / SKU','Store','Price','Available / held','Listing','Actions'].map(label=>`<th>${label}</th>`).join('')}</tr></thead><tbody>${data.products.map(p=>`<tr><td><div class="avatarline">${image(p,'api-thumb')}<div><b>${e(p.name)}</b><div class="small subtle">${e(p.sku)}</div></div></div></td><td>${e(p.seller)}</td><td>${fmt(p.price)}</td><td>${p.primary} available<br><span class="subtle">${p.reserved} held · ${p.onHand} on hand</span></td><td>${p.published?'Published':'Archived'}</td><td><div class="api-tab-actions">${scope==='admin'?`<button class="btn mini ghost" data-api-edit-product="${e(p.id)}">Edit</button>`:action('Edit','edit-product',p.id)}${action('Stock history','stock',p.id,`data-scope="${scope}"`)}${scope==='admin'&&p.published?action('Unpublish','moderate',p.id):''}</div></td></tr>`).join('')||'<tr><td colspan="6"><div class="api-empty"><h3>No products yet</h3><p>Create your first listing.</p></div></td></tr>'}</tbody></table></div>${extrasUI?.pager(data.catalogPagination||data.pagination,scope==='seller'?'seller-products':'staff-catalog')||''}</section>`;}
  function staffOrders(data,scope='admin'){return `<section class="surface section-box"><h2>${scope==='seller'?'Seller orders & fulfillment':'Orders & fulfillment'}</h2><p class="notice">Local test orders only. Update each seller shipment in sequence. Dispatch with a tracking reference, then optionally connect automatic tracking.</p>${data.orders.map(order=>`<article class="commerce-order surface block"><div class="toolbar"><b>${e(order.id)}</b>${badge(order.status)}</div><p class="small">${order.lines.map(line=>e(line.name)+(line.sku?' / '+e(line.sku):'')+' × '+(line.fulfillableQty??line.qty)).join('<br>')}</p><p><b>${fmt(order.total)}</b>${order.refunded?'<span class="small"> ? Test refunds '+fmt(order.refunded)+'</span>':''}${order.customerEmail?' · '+e(order.customerEmail):''}</p>${order.returns?.length?`<details><summary>Store returns (${order.returns.length})</summary>${order.returns.map(r=>`<p>${e(r.status)}: ${r.items.map(item=>e(order.lines.find(l=>l.id===item.id)?.name||item.id)+' x '+item.qty).join(', ')}</p>`).join('')}</details>`:''}${order.delivery?`<details><summary>Delivery address</summary><p class="small">${e(order.delivery.name)} · ${e(order.delivery.phone)}<br>${e(order.delivery.address)}, ${e(order.delivery.barangay)}, ${e(order.delivery.city)}, ${e(order.delivery.province)} ${e(order.delivery.postal)}</p></details>`:''}${order.shipments.map(sh=>`<div class="commerce-shipment"><div><b>${e(sh.seller)}</b> · ${e(labels[sh.status]||sh.status)}${sh.tracking?`<p class="small subtle">${e(sh.courier)} · ${e(sh.tracking)}</p>`:''}</div>${stageNext[sh.status]?action('Mark '+labels[stageNext[sh.status]],'shipment',sh.id,`data-scope="${scope}"`):''}${extrasUI?.shippingControls(sh,scope)||''}</div>`).join('')}<div class="api-tab-actions">${scope==='admin'&&order.payment?.mode!=='paymongo-test'&&['awaiting_gateway','pending_payment'].includes(order.status)?`<button class="btn mini danger" data-api-cancel-order="${e(order.id)}">Cancel unpaid order</button>`:''}${scope==='admin'&&order.payment?.status==='paid'&&order.payment?.mode==='local-test'?action('Review test refund','refund',order.id):''}</div></article>`).join('')||'<div class="api-empty"><h3>No orders yet</h3><p>Orders appear here after checkout.</p></div>'}${extrasUI?.pager(data.orderPagination||data.pagination,scope==='seller'?'seller-orders':'staff-orders')||''}</section>`;}
  async function loadSeller(){const ownerId=state.user?.id,store=await api('/seller/store');if(ownerId!==state.user?.id)return;if(state.profile)state.profile.store=store.store;if(store.store.status!=='approved'){state.sellerData=null;throw Error('Your store is '+store.store.status+'. Review your account notifications for the management decision.');}const [catalog,orders,reports,notifications,posInventory]=await Promise.all([api('/seller/catalog?page='+(state.sellerProductPage||1)+'&limit=20'),api('/seller/orders?page='+(state.sellerOrderPage||1)+'&limit=20'),api('/seller/reports?'+(state.reportFilters?.seller||'')),api('/account/notifications'),api('/seller/pos/inventory')]);if(ownerId!==state.user?.id)return;state.sellerData={...catalog,...orders,reports,posInventory,notifications:notifications.notifications,catalogPagination:catalog.pagination,orderPagination:orders.pagination,store:store.store};}

  function sellerPage(){
    if(!state.user)return login();
    if(state.profile?.store?.status!=='approved')return `<div class="wrap page"><section class="surface section-box api-auth">${sellerOverview()}<button class="btn ghost" data-page="account">My account</button></section></div>`;
    if(!state.sellerData){if(!state.sellerLoading){state.sellerLoading=true;loadSeller().then(()=>render()).catch(error=>{state.message=error.message;state.error=true;ui.page='account';render();}).finally(()=>{state.sellerLoading=false;});}return '<div class="wrap page"><div class="ui-skeleton-label" role="status">Loading seller workspace…</div></div>';}
    const store=state.sellerData.store;
    return `<div class="wrap page ops-seller"><div class="section-head"><div><span class="eyebrow">SELLER WORKSPACE</span><h1>${e(store.name)}</h1><p>Manage your products, stock and shipments.</p></div><button class="btn ghost" data-page="account">My account</button></div>${state.message?`<div class="api-status ${state.error?'error':'success'}" role="status">${e(state.message)}</div>`:''}<div class="ops-subnav">${[['seller-products','Products'],['seller-inventory','Inventory'],['seller-orders','Orders'],['seller-store','Store profile'],['seller-reports','Reports']].map(([id,label])=>action(label,'jump',id)).join('')}${action('Refresh workspace','seller-open')}</div>${operationalKPIs(state.sellerData.reports||{})}<div class="stack"><div id="seller-products">${catalogView(state.sellerData,'seller')}</div>${inventoryView(state.sellerData.reports||{})}${posView(state.sellerData.posInventory,'seller')}<div id="seller-orders">${staffOrders(state.sellerData,'seller')}</div><section id="seller-store" class="surface section-box"><h2>Store profile</h2><p>Publication: ${badge(store.status)} &middot; Account: active</p><details><summary>Notifications and management decisions</summary>${(state.sellerData.notifications||[]).slice(0,15).map(n=>`<p>${e(n.message)}</p>`).join('')||'<p>No notifications.</p>'}</details><form id="apiCommerceStoreForm" class="api-form"><input type="hidden" name="revision" value="${store.revision}">${input('tagline','Store tagline',store.tagline,'text','required minlength="2" maxlength="140"')}${input('headline','Store headline',store.headline,'text','required minlength="2" maxlength="140"')}${input('logo','Logo URL',store.logo||'')}${input('banner','Banner URL',store.banner||'')}${input('logoFile','Upload store logo','','file','accept="image/png,image/jpeg,image/webp"')}${input('bannerFile','Upload store banner','','file','accept="image/png,image/jpeg,image/webp"')}<div class="field"><label>Description</label><textarea name="description" required minlength="2" maxlength="1000" rows="3">${e(store.description)}</textarea></div><button class="btn primary">Save store profile</button></form></section>${reportView(state.sellerData.reports||{},'seller')}</div></div>`;
  }

  function businessTable(head,rows){return `<div class="table-wrap"><table><thead><tr>${head.map(v=>`<th>${e(v)}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${head.length}">No records for this selection.</td></tr>`}</tbody></table></div>`;}
  function operationalKPIs(data){return `<div class="kpis ops-kpis">${Object.entries(data.kpis||{}).filter(([,v])=>v!==null).map(([key,value])=>`<div class="surface kpi"><span>${e(({pendingSellers:'Pending applications',approvedSellers:'Approved stores',suspendedSellers:'Suspended stores',publishedProducts:'Published products',ordersAwaitingAction:'Orders awaiting action',openReturns:'Open returns',openSupport:'Open support',lowStock:'Low-stock alerts'})[key]||key)}</span><strong>${value}</strong></div>`).join('')}</div>`;}
  function reportView(data,scope='admin'){return `<section class="surface section-box ops-reports" id="seller-reports"><div class="toolbar"><div><h2>${scope==='seller'?'Store':'Business'} reports</h2><p>Order-date cohorts in UTC. Store figures include only that store's lines.</p></div>${action('Export CSV','export-report',scope)}</div><form id="apiCommerceReportFilters" class="ops-filters"><input type="hidden" name="scope" value="${scope}">${input('from','From',data.from||'','date')}${input('to','Through',data.to||'','date')}${scope==='admin'?`<div class="field"><label for="report-store">Store</label><select id="report-store" name="storeId"><option value="">All stores</option>${(data.stores||[]).map(store=>`<option value="${e(store.id)}" ${store.id===data.storeId?'selected':''}>${e(store.name)}</option>`).join('')}</select></div>`:''}<button class="btn primary">Apply report filters</button></form><p class="notice">${e(data.notice||'Test figures only; no real-money revenue.')}</p><div class="kpis">${[['Orders',data.orders||0],['Net test product receipts',fmt(data.testProductReceipts||0)],['Test item refunds',fmt(data.testItemRefunds||0)],['Return rate',((data.returnRate||0)*100).toFixed(1)+'%'],['Cancellation rate',((data.cancellationRate||0)*100).toFixed(1)+'%']].map(([name,v])=>`<div class="kpi"><span>${e(name)}</span><strong>${e(v)}</strong></div>`).join('')}</div>${[['Orders by status','byStatus'],['Orders by date','byDate'],['Payment status','payments'],['Fulfillment status','fulfillment']].map(([title,key])=>`<h3>${title}</h3>${businessTable([title,'Count'],(data[key]||[]).map(r=>`<tr><td>${e(r.status)}</td><td>${r.count}</td></tr>`))}`).join('')}<h3>Product performance</h3>${businessTable(['Product / variant','Paid units after refunds','Net test receipts'],(data.byProduct||[]).map(r=>`<tr><td>${e(r.name)}</td><td>${r.units}</td><td>${fmt(r.testNet)}</td></tr>`))}<h3>Store performance</h3>${businessTable(['Store','Orders','Paid units','Net test receipts'],(data.byStore||[]).map(r=>`<tr><td>${e(r.name)}</td><td>${r.orders}</td><td>${r.units}</td><td>${fmt(r.testNet)}</td></tr>`))}<h3>Store activity (current listings, selected order period)</h3>${businessTable(['Store','Status','Products','Published','Orders'],(data.storeActivity||[]).map(r=>`<tr><td>${e(r.name)}</td><td>${badge(r.status)}</td><td>${r.products}</td><td>${r.published}</td><td>${r.orders}</td></tr>`))}<h3>Low-stock alerts (current inventory)</h3>${businessTable(['Product / SKU','Store','Available'],(data.lowStock||[]).map(r=>`<tr><td>${e(r.name)} / ${e(r.sku)}</td><td>${e(r.store)}</td><td>${r.available}</td></tr>`))}<h3>Inventory movements (selected period)</h3>${businessTable(['Movement','Stock delta','Entries'],(data.inventoryMovements||[]).map(r=>`<tr><td>${e(r.kind)}</td><td>${r.quantity}</td><td>${r.movements}</td></tr>`))}</section>`;}
  function inventoryView(data){return `<section id="seller-inventory" class="surface section-box"><h2>Inventory</h2><p>Available stock excludes active reservations. Variant stock appears under its own SKU.</p>${businessTable(['Product / variant','SKU','On hand','Reserved','Available',''],(data.inventory||[]).map(r=>`<tr><td>${e(r.name)}</td><td>${e(r.sku)}</td><td>${r.onHand}</td><td>${r.reserved}</td><td>${r.available}</td><td>${action('Movements / adjust','stock',r.id,'data-scope="seller"')}</td></tr>`))}<h3>Low-stock alerts</h3>${businessTable(['Product','SKU','Available'],(data.lowStock||[]).map(r=>`<tr><td>${e(r.name)}</td><td>${e(r.sku)}</td><td>${r.available}</td></tr>`))}</section>`;}
  function posView(data,scope){return `<section class="surface section-box api-history"><h2>POS backup inventory</h2><p class="notice">Reference only. These quantities are separate from sellable e-commerce stock and cannot be added to cart or merged automatically.</p>${(data?.stores||[]).map(store=>`<article class="api-setting-card" data-pos-fresh-until="${store.status==='connected'?store.freshUntil||'':''}"><div class="toolbar"><h3>${e(store.storeName)}</h3><span data-pos-status>${badge(store.status)}</span></div><p class="small">Last successful refresh: ${store.lastUpdateAt?e(new Date(store.lastUpdateAt).toLocaleString()):'Never'} ? Source snapshot: ${store.sourceAt?e(new Date(store.sourceAt).toLocaleString()):'Unavailable'} ? Last attempt: ${store.lastAttemptAt?e(new Date(store.lastAttemptAt).toLocaleString()):'Never'}</p><p class="notice warn" data-pos-stale ${store.stale?'':'hidden'}>Stale or unavailable reference. Do not treat it as current stock.</p>${store.error?`<p role="status">${e(store.error)}</p>`:''}${store.items?.length?businessTable(['Product / variant','Online SKU','POS SKU','Backup quantity','Status'],store.items.map(p=>`<tr><td>${e(p.name)}</td><td>${e(p.sku)}</td><td>${e(p.posSku)}</td><td>${p.backupQuantity===null?'Unavailable':p.backupQuantity}</td><td data-pos-item-status>${e(p.status.replaceAll('_',' '))}</td></tr>`)):''}${!['disabled','unmapped','mapping_error'].includes(store.status)?action('Refresh POS reference','pos-refresh',store.storeId,`data-scope="${scope}"`):'<p class="small">Private endpoint, credentials and exact store/SKU mappings must be configured locally.</p>'}</article>`).join('')||'<p>No stores available.</p>'}</section>`;}
  function customersView(data){return `<section class="surface section-box"><h2>Customer accounts</h2><p>Contact details are masked. Roles and passwords cannot be changed here. Account recovery uses the verified email recovery flow.</p><form id="apiCommerceCustomerSearch" class="ops-filters">${input('q','Name or email',new URLSearchParams(state.customerFilters||'').get('q')||'')}<div class="field"><label for="customer-status">Status</label><select id="customer-status" name="status"><option value="">All statuses</option>${['pending','active','suspended'].map(v=>`<option ${(new URLSearchParams(state.customerFilters||'').get('status')===v)?'selected':''}>${v}</option>`).join('')}</select></div><button class="btn primary">Search accounts</button></form>${businessTable(['Customer','Masked email','Verification','Status','Action'],(data.customers||[]).map(c=>`<tr><td>${e(c.name)}</td><td>${e(c.email)}</td><td>${c.verified?'Verified':'Pending'}</td><td>${badge(c.status)}</td><td>${c.verified?`<button class="btn mini ghost" data-api-customer="${e(c.id)}|${c.status==='suspended'?'active':'suspended'}">${c.status==='suspended'?'Restore':'Suspend'}</button>`:''}</td></tr>`))}${data.pagination?.pages>1?`<nav class="feature-pagination">${action('Previous','customers-page',data.pagination.page-1,data.pagination.page===1?'disabled':'')}<span>Page ${data.pagination.page} of ${data.pagination.pages}</span>${action('Next','customers-page',data.pagination.page+1,data.pagination.page>=data.pagination.pages?'disabled':'')}</nav>`:''}</section>`;}

  function staffContent(tab){
    if(state.user?.role==='management'&&tab==='overview')return operationalKPIs(state.adminData.overview||{})+`<section class="surface section-box"><h2>Operations dashboard</h2><p class="notice">${e(state.adminData.overview?.notice||'Test transactions only; no real money moved.')}</p><div class="kpis">${[['Net test product receipts',fmt(state.adminData.overview?.testProductReceipts||0)],['Test item refunds',fmt(state.adminData.overview?.testItemRefunds||0)],['Pending test payments',state.adminData.overview?.pendingPayment||0]].map(([label,value])=>`<div class="kpi"><span>${e(label)}</span><strong>${e(value)}</strong></div>`).join('')}</div><div class="api-tab-actions">${[['sellers','Review sellers'],['orders','Review orders'],['returns','Review returns'],['reports','Business reports']].map(([tab,label])=>`<button class="btn ghost" data-api-tab="${tab}">${label}</button>`).join('')}</div></section>`;
    if(tab==='customers'&&state.adminData.customers)return customersView(state.adminData.customers);
    const extended=extrasUI?.staffContent(tab);if(extended!==undefined)return extended;
    const data=state.adminData[tab];if(!data)return;
    if(tab==='catalog')return catalogView(data)+posView(state.adminData.posInventory,'admin');
    if(tab==='orders')return staffOrders(data);
    if(tab==='sellers')return `<section class="surface section-box"><h2>Seller applications & stores</h2><p class="subtle">Approve individual stores before sellers can publish listings.</p>${data.stores.map(store=>`<article class="commerce-address"><div class="toolbar"><h3>${e(store.name)}</h3>${badge(store.status)}</div><p>${e(store.description)}</p><p class="small subtle">Owner account: ${e(store.ownerStatus||'No linked account')} &middot; ${e(store.ownerName)}${store.ownerEmail?' · '+e(store.ownerEmail):''}</p><div class="api-tab-actions">${['approved','rejected','suspended'].filter(status=>status!==store.status).map(status=>action(status==='approved'?'Approve':status==='rejected'?'Reject':'Suspend','store-status',store.id,`data-status="${status}"`)).join('')}</div><details><summary>Decision history</summary>${(store.decisions||[]).map(d=>`<p>${e(d.status)}: ${e(d.reason||'Profile updated')} &middot; ${e(new Date(d.createdAt).toLocaleString())}</p>`).join('')||'<p>No recorded decisions.</p>'}</details></article>`).join('')}</section>`;
    if(tab==='returns')return `<section class="surface section-box"><h2>Returns</h2>${data.returns.map(request=>`<article class="commerce-address"><b>${e(request.order_id)}</b> ${badge(request.status)}<p>${e(request.reason)}</p><div class="api-tab-actions">${(request.status==='requested'?['approved','rejected']:request.status==='approved'?['received']:[]).map(status=>action('Mark '+status,'return-status',request.id,`data-status="${status}"`)).join('')}</div></article>`).join('')||'<div class="api-empty"><h3>No return requests</h3></div>'}</section>`;
    if(tab==='support')return `<section class="surface section-box"><h2>Customer support</h2>${ticketsView(data.tickets,true)}</section>`;
    if(tab==='reports')return reportView(data);
  }
  function renderPage(){
    if(ui.page==='seller-center')return sellerPage();
    if(ui.page==='forgot-password')return `<div class="wrap page"><section class="surface section-box api-auth"><span class="eyebrow">ACCOUNT RECOVERY</span><h1>Forgot your password?</h1><p>We’ll email a single-use reset link if your account is active.</p><form id="apiCommerceForgotForm" class="api-form">${input('email','Gmail address',state.registration.email,'email','required autocomplete="email"')}<button class="btn primary full">Send reset link</button></form><button class="api-link" data-page="login">Back to sign in</button></section></div>`;
    if(ui.page==='reset-password')return `<div class="wrap page"><section class="surface section-box api-auth"><span class="eyebrow">ACCOUNT RECOVERY</span><h1>Choose a new password</h1><form id="apiCommerceResetForm" class="api-form">${input('password','New password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<button class="btn primary full">Update password</button></form><button class="api-link" data-page="forgot-password">Request a new link</button></section></div>`;
    if(ui.page==='checkout'&&state.checkoutDone)return paymentView(state.checkoutDone);
  }
  function findOrder(id,scope='admin'){return (scope==='seller'?state.sellerData?.orders:state.adminData.orders?.orders)?.find(order=>order.id===id);}
  function formError(form,message){let box=form.querySelector('[role=alert]');if(!box){box=document.createElement('div');box.className='api-status error';box.setAttribute('role','alert');form.prepend(box);}box.textContent=message;box.tabIndex=-1;box.focus();}
  async function refreshScope(scope){await refreshCatalog();if(scope==='seller')await loadSeller();else await loadAdmin(state.tab);}
  extrasUI=window.installCustomerFeatures?.({state,api,loadOrders,loadAdmin,refreshCatalog,loadSeller,notice,input,action,badge})||null;
  // Event handlers are registered before the legacy adapter's handlers.
  document.addEventListener('submit',async event=>{
    const form=event.target,formId=form.getAttribute('id')||'';if(!formId.startsWith('apiCommerce'))return;event.preventDefault();event.stopImmediatePropagation();if(state.busy||!form.reportValidity())return;
    const data=Object.fromEntries(new FormData(form));state.busy=true;form.setAttribute('aria-busy','true');const button=form.querySelector('button[type=submit],button:not([type])');if(button){button.disabled=true;button.classList.add('is-loading');}
    let success=false,message='Saved.',operationError=false;
    try{
      if(formId==='apiCommerceReportFilters'){state.reportFilters||={};const query=new URLSearchParams();for(const key of ['from','to','storeId'])if(data[key])query.set(key,data[key]);state.reportFilters[data.scope]=query.toString();if(data.scope==='seller')await loadSeller();else await loadAdmin('reports');message='Report filters applied.';
      }else if(formId==='apiCommerceStockAdjustment'){await api('/'+data.scope+'/inventory/'+encodeURIComponent(data.id)+'/adjustments',{method:'POST',body:{revision:Number(data.revision),delta:Number(data.delta),reason:data.reason}});closeOverlay();await refreshScope(data.scope);message='Stock adjustment recorded.';
      }else if(formId==='apiCommercePosRefresh'){const suffix=data.scope==='admin'?'?storeId='+encodeURIComponent(data.storeId):'';const result=await api('/'+data.scope+'/pos/inventory/refresh'+suffix,{method:'POST',body:{reason:data.reason}});closeOverlay();if(data.scope==='seller')await loadSeller();else state.adminData.posInventory=await api('/admin/pos/inventory');message=result.stores[0].status==='unavailable'?'POS reference unavailable; last successful values are stale.':'POS reference refreshed; e-commerce stock is unchanged.';operationError=result.stores[0].status==='unavailable';
      }else if(formId==='apiCommerceCustomerSearch'){state.customerFilters=new URLSearchParams({q:data.q,status:data.status}).toString();state.listPages.customers=1;await loadAdmin('customers');message='Customer results updated.';
      }else if(formId==='apiCommerceCustomerStatus'){await api('/admin/customers/'+encodeURIComponent(data.id),{method:'PATCH',body:{status:data.status,reason:data.reason}});closeOverlay();await loadAdmin('customers');message='Customer status updated; prior sessions invalidated.';
      }else if(formId==='apiCommerceModeration'){await api('/admin/catalog/'+encodeURIComponent(data.id),{method:'PATCH',body:{revision:Number(data.revision),published:false,reason:data.reason}});closeOverlay();await refreshCatalog();await loadAdmin('catalog');message='Listing unpublished and seller notified.';
      }else if(formId==='apiCommerceProductForm'){
        const scope=data.scope,id=data.id,body={name:data.name,sku:data.sku,category:data.category,subcategory:data.subcategory||'',description:data.description,price:Number(data.price),was:Number(data.was),primary:Number(data.primary),published:!!data.published,photo:data.photo,spec:{},reason:data.reason};
        for(const line of data.spec.split('\n').filter(line=>line.trim())){const colon=line.indexOf(':');if(colon<1)throw Error('Use Name: Value for each specification.');body.spec[line.slice(0,colon).trim()]=line.slice(colon+1).trim();}
        const file=form.querySelector('[name=image]').files[0];if(file){if(file.size>750000)throw Error('Use an image smaller than 750 KB.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Could not read the selected image.'));reader.readAsDataURL(file);});body.photo=(await api('/'+scope+'/media',{method:'POST',body:{base64}})).url;}
        if(id)body.revision=Number(data.revision);else body.storeId=data.storeId;if(!body.reason)delete body.reason;
        await api('/'+scope+'/catalog'+(id?'/'+encodeURIComponent(id):''),{method:id?'PATCH':'POST',body});closeOverlay();await refreshScope(scope);message=id?'Product updated.':'Product created.';
      }else if(formId==='apiCommerceProfileForm'){const result=await api('/account',{method:'PATCH',body:{name:data.name,phone:data.phone}});state.profile=result.profile;state.user={...state.user,name:result.profile.name};db.profile.name=result.profile.name;message='Profile updated.';
      }else if(formId==='apiCommercePasswordForm'){const result=await api('/account/password',{method:'POST',body:{currentPassword:data.currentPassword,password:data.password}});adoptSession({user:null});afterLogout();ui.page='login';message=result.message;
      }else if(formId==='apiCommerceAddressForm'){const body={...Object.fromEntries(['name','phone','address','barangay','city','province','postal'].map(key=>[key,data[key]])),default:!!data.default,...(data.id?{revision:Number(data.revision)}:{})};const result=await api('/account/addresses'+(data.id?'/'+data.id:''),{method:data.id?'PATCH':'POST',body});state.addresses=result.addresses;closeOverlay();message='Address saved.';
      }else if(formId==='apiCommerceSellerApplication'){const result=await api('/seller/application',{method:'POST',body:{name:data.name,tagline:data.tagline,description:data.description}});state.profile.store=result.store;message='Seller application submitted for Management review.';
      }else if(formId==='apiCommerceStoreForm'){const images={logo:data.logo,banner:data.banner};for(const key of ['logo','banner']){const file=form.elements[key+'File'].files[0];if(file){if(file.size>750000)throw Error('Use an image up to 750 KB.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Unable to read store image.'));reader.readAsDataURL(file);});images[key]=(await api('/seller/media',{method:'POST',body:{base64}})).url;}}const result=await api('/seller/store',{method:'PATCH',body:{revision:Number(data.revision),tagline:data.tagline,headline:data.headline,description:data.description,...images}});state.sellerData.store=result.store;state.profile.store=result.store;await refreshCatalog();message='Store profile updated.';
      }else if(formId==='apiCommerceForgotForm'){message=(await api('/auth/forgot-password',{method:'POST',body:{email:data.email}})).message;form.reset();
      }else if(formId==='apiCommerceResetForm'){message=(await api('/auth/reset-password',{method:'POST',body:{token:state.resetToken,password:data.password}})).message;state.resetToken=null;adoptSession({user:null});afterLogout();ui.page='login';
      }else if(formId==='apiCommerceShipmentForm'){await api('/'+data.scope+'/shipments/'+data.id,{method:'PATCH',body:{revision:Number(data.revision),status:data.status,courier:data.courier,tracking:data.tracking}});closeOverlay();await refreshScope(data.scope);message='Shipment updated.';
      }else if(formId==='apiCommerceStoreStatusForm'){await api('/admin/sellers/'+data.id,{method:'PATCH',body:{revision:Number(data.revision),status:data.status,reason:data.reason}});closeOverlay();await loadAdmin('sellers');await refreshCatalog();message='Seller store status updated.';
      }else if(formId==='apiCommerceReturnForm'){await api('/orders/'+data.id+'/returns',{method:'POST',body:{reason:data.reason}});closeOverlay();await loadOrders();message='Return request submitted.';
      }else if(formId==='apiCommerceRefundForm'){await api('/admin/orders/'+data.id+'/refund',{method:'POST',body:{revision:Number(data.revision),reason:data.reason,restock:!!data.restock}});closeOverlay();await loadAdmin('orders');await refreshCatalog();message='Local test refund recorded. No real money moved.';
      }else if(formId==='apiCommerceSupportForm'){await api('/account/support',{method:'POST',body:{subject:data.subject,message:data.message}});state.tickets=(await api('/account/support')).tickets;message='Support request sent.';
      }else if(formId.startsWith('apiCommerceReply-')){await api('/'+data.scope+'/support/'+data.id,{method:'POST',body:{revision:Number(data.revision),message:data.message,status:data.closed?'closed':'open'}});if(data.scope==='admin')await loadAdmin('support');else state.tickets=(await api('/account/support')).tickets;message='Reply sent.';}
      success=true;state.message=message;state.error=operationError;
    }catch(error){formError(form,error.message);}finally{state.busy=false;form.removeAttribute('aria-busy');if(button){button.disabled=false;button.classList.remove('is-loading');}if(success){render();if(!['account','seller-center'].includes(ui.page))notify(message);}}
  },true);
  document.addEventListener('click',async event=>{
    const button=event.target.closest('button,a');if(!button)return;
    if(button.hasAttribute('data-api-customer')){event.preventDefault();event.stopImmediatePropagation();if(state.busy)return;const [id,status]=button.dataset.apiCustomer.split('|');openOverlay(status==='suspended'?'Suspend customer account':'Reactivate customer account',`<form id="apiCommerceCustomerStatus" class="api-form"><input type="hidden" name="id" value="${e(id)}"><input type="hidden" name="status" value="${e(status)}"><p>${status==='suspended'?'Access and existing sessions will be revoked.':'The verified account may sign in again; previous sessions remain revoked.'}</p>${input('reason','Decision reason','','text','required minlength="5" maxlength="200"')}<button class="btn primary">Confirm ${status==='suspended'?'suspension':'reactivation'}</button></form>`,true);return;}
    const attr=[...button.attributes].find(item=>item.name.startsWith('data-commerce-'));if(!attr)return;event.preventDefault();event.stopImmediatePropagation();if(state.busy)return;
    const value=attr.value;state.busy=true;const disabled=button.disabled;button.disabled=true;button.classList.add('is-loading');
    try{
      if(attr.name==='data-commerce-pos-refresh'){openOverlay('Refresh POS reference inventory',`<form id="apiCommercePosRefresh" class="api-form"><input type="hidden" name="scope" value="${e(button.dataset.scope)}"><input type="hidden" name="storeId" value="${e(value)}"><p>Fetch reference quantities only. E-commerce stock and reservations remain separate.</p>${input('reason','Refresh reason','','text','required minlength="5" maxlength="200"')}<button class="btn primary">Refresh reference</button></form>`,true);}
      else if(attr.name==='data-commerce-jump'){document.getElementById(value)?.scrollIntoView({behavior:'instant',block:'start'});return;}
      else if(attr.name==='data-commerce-customers-page'){state.listPages.customers=Number(value);await loadAdmin('customers');render();}
      else if(attr.name==='data-commerce-moderate'){const p=state.adminData.catalog.products.find(p=>p.id===value);openOverlay('Unpublish listing',`<form id="apiCommerceModeration" class="api-form"><input type="hidden" name="id" value="${e(p.id)}"><input type="hidden" name="revision" value="${p.revision}"><p>${e(p.name)} will be removed from public browsing. Inventory and historical orders are preserved.</p>${input('reason','Moderation reason','','text','required minlength="5" maxlength="200"')}<button class="btn primary">Unpublish and notify seller</button></form>`,true);}
      else if(attr.name==='data-commerce-export-report'){const data=value==='seller'?state.sellerData.reports:state.adminData.reports;const cell=value=>'"'+String(value??'').replace(/^\s*[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=[['TEST FIGURES ONLY - shipping excluded'],['Period',data.from||'All dates',data.to||'All dates'],['Orders',data.orders],['Net test product receipts PHP',data.testProductReceipts],['Test item refunds PHP',data.testItemRefunds],['Return rate',data.returnRate],['Cancellation rate',data.cancellationRate],[],['Product / variant','Paid units after refunds','Net test receipts PHP'],...(data.byProduct||[]).map(p=>[p.name,p.units,p.testNet]),[],['Store','Orders','Paid units','Net test receipts PHP'],...(data.byStore||[]).map(r=>[r.name,r.orders,r.units,r.testNet]),...['byStatus','byDate','payments','fulfillment'].flatMap(key=>[[],[key,'Count'],...(data[key]||[]).map(r=>[r.status,r.count])]),[],['Current low stock / SKU','Store','Available'],...(data.lowStock||[]).map(r=>[r.name+' / '+r.sku,r.store,r.available]),[],['Inventory movement','Stock delta','Entries'],...(data.inventoryMovements||[]).map(r=>[r.kind,r.quantity,r.movements])];const url=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='salesync-test-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
      else if(attr.name==='data-commerce-tab'){state.accountTab=value;state.message='';render();}
      else if(attr.name==='data-commerce-address')openOverlay(value==='new'?'Add delivery address':'Edit delivery address',addressForm(state.addresses.find(address=>address.id===value)),true);
      else if(attr.name==='data-commerce-delete-address'){const address=state.addresses.find(address=>address.id===value);state.addresses=(await api('/account/addresses/'+address.id,{method:'DELETE',body:{revision:address.revision}})).addresses;notice('Address removed.');}
      else if(attr.name==='data-commerce-read-notifications'){state.notifications=(await api('/account/notifications',{method:'PATCH',body:{read:true}})).notifications;render();}
      else if(attr.name==='data-commerce-seller-open'){await loadSeller();ui.page='seller-center';state.message='';render();window.scrollTo({top:0,behavior:'instant'});}
      else if(attr.name==='data-commerce-new-product')openProduct(null,value);
      else if(attr.name==='data-commerce-edit-product')openProduct(state.sellerData.products.find(p=>p.id===value),'seller');
      else if(attr.name==='data-commerce-stock'){const result=await api('/'+button.dataset.scope+'/inventory/'+value);openOverlay('Inventory history',`<h3>${e(result.product.name)}</h3><p>${result.product.onHand} on hand · ${result.product.reserved} reserved · ${result.product.primary} available</p>${!result.product.variationGroups?.length?`<form id="apiCommerceStockAdjustment" class="api-form"><input type="hidden" name="scope" value="${e(button.dataset.scope)}"><input type="hidden" name="id" value="${e(value)}"><input type="hidden" name="revision" value="${result.product.revision}">${input('delta','Quantity adjustment (add or remove units)','','number','required min="-1000000" max="1000000" step="1"')}${input('reason','Adjustment reason','','text','required minlength="5" maxlength="200"')}<button class="btn primary">Record stock adjustment</button></form>`:'<p>Adjust each variation separately in Inventory.</p>'}${result.movements.map(move=>`<div class="api-diff"><b>${e(move.kind)}</b> · Stock ${move.delta>=0?'+':''}${move.delta} · Reserved ${move.reservedDelta>=0?'+':''}${move.reservedDelta}<br>${e(move.reason)}<br><span class="subtle">${e(new Date(move.createdAt).toLocaleString())}</span></div>`).join('')}`);}
      else if(attr.name==='data-commerce-store-status'){const store=state.adminData.sellers.stores.find(s=>s.id===value);openOverlay('Review seller store',`<h3>${e(store.name)}</h3><p>Set status to <b>${e(button.dataset.status)}</b>.</p><form id="apiCommerceStoreStatusForm" class="api-form"><input type="hidden" name="id" value="${e(value)}"><input type="hidden" name="revision" value="${store.revision}"><input type="hidden" name="status" value="${e(button.dataset.status)}">${input('reason','Review reason','','text','required minlength="5" maxlength="200"')}<button class="btn primary">Confirm store status</button></form>`,true);}
      else if(attr.name==='data-commerce-pay-order'){state.checkoutDone=state.orders.find(order=>order.id===value);ui.paymentOrderId=value;ui.page='checkout';render();window.scrollTo({top:0,behavior:'instant'});}
      else if(attr.name==='data-commerce-hosted'){const result=await api('/orders/'+encodeURIComponent(value)+'/payment/'+button.dataset.operation,{method:'POST',body:{}});state.checkoutDone=result.order;await loadOrders();if(button.dataset.operation==='checkout'&&result.checkoutUrl){location.assign(result.checkoutUrl);return;}notice(result.pending?'Payment pending. No verified successful payment yet.':'Payment status checked with PayMongo.');}
      else if(attr.name==='data-commerce-payment'){const result=await api('/payments/'+value+'/simulate',{method:'POST',body:{outcome:button.dataset.outcome}});state.checkoutDone=result.order;await loadOrders();await refreshCatalog();state.notifications=(await api('/account/notifications')).notifications;render();}
      else if(attr.name==='data-commerce-cancel-order'){const order=state.orders.find(order=>order.id===value);const provider=order.payment?.mode==='paymongo-test',result=await api('/orders/'+value+(provider?'/payment/cancel':'/cancel'),{method:'POST',body:provider?{}:{revision:order.revision}});await loadOrders();await refreshCatalog();notice(result.pending?'Payment is processing; reservation retained.':'Unpaid checkout closed; reservation released.');}
      else if(attr.name==='data-commerce-shipment'){const scope=button.dataset.scope,orders=scope==='seller'?state.sellerData.orders:state.adminData.orders.orders,sh=orders.flatMap(order=>order.shipments).find(sh=>sh.id===value);openOverlay('Update shipment',`<p>${e(sh.seller)} · ${e(labels[sh.status])} → <b>${e(labels[stageNext[sh.status]])}</b></p><form id="apiCommerceShipmentForm" class="api-form"><input type="hidden" name="scope" value="${scope}"><input type="hidden" name="id" value="${e(sh.id)}"><input type="hidden" name="revision" value="${sh.revision}"><input type="hidden" name="status" value="${stageNext[sh.status]}">${input('courier','Courier',sh.courier,'text',stageNext[sh.status]==='shipped'?'required minlength="2" maxlength="100"':'maxlength="100"')}${input('tracking','Tracking reference',sh.tracking,'text',stageNext[sh.status]==='shipped'?'required minlength="2" maxlength="100"':'maxlength="100"')}<button class="btn primary">Confirm shipment update</button></form>`,true);}
      else if(attr.name==='data-commerce-return-order')openOverlay('Request a return',`<form id="apiCommerceReturnForm" class="api-form"><input type="hidden" name="id" value="${e(value)}"><div class="field"><label for="return-reason">Reason</label><textarea id="return-reason" name="reason" required minlength="10" maxlength="1000" rows="4"></textarea></div><button class="btn primary">Submit return request</button></form>`,true);
      else if(attr.name==='data-commerce-return-status'){const request=state.adminData.returns.returns.find(request=>request.id===value);await api('/admin/returns/'+value,{method:'PATCH',body:{revision:request.revision,status:button.dataset.status}});await loadAdmin('returns');notice('Return status updated.');}
      else if(attr.name==='data-commerce-refund'){const order=findOrder(value);openOverlay('Review local test refund',`<p class="notice warn">Full local test refund for ${fmt(order.total)}. Dispatched goods must be marked received in Returns first.</p><form id="apiCommerceRefundForm" class="api-form"><input type="hidden" name="id" value="${e(order.id)}"><input type="hidden" name="revision" value="${order.revision}">${input('reason','Refund reason','','text','required minlength="5" maxlength="200"')}<label class="commerce-check"><input type="checkbox" name="restock"> Return these units to saleable stock</label><button class="btn primary">Record test refund</button></form>`,true);}
    }catch(error){if(attr.name==='data-commerce-payment'&&state.checkoutDone){try{state.checkoutDone=(await api('/orders/'+state.checkoutDone.id)).order;}catch{}}notice(error.message,true);}finally{state.busy=false;button.disabled=disabled;button.classList.remove('is-loading');}
  },true);
  document.addEventListener('change',event=>{if(event.target.matches('[data-commerce-delivery]')){const address=state.addresses.find(address=>address.id===event.target.value);if(!address)return;ui.shipping={...address};for(const key of ['name','phone','address','barangay','city','province','postal']){const field=document.querySelector('#apiCheckoutForm [name='+key+']');if(field)field.value=address[key];}}});
  window.addEventListener('salesync:restore-payment',async event=>{try{const result=await api('/orders/'+encodeURIComponent(event.detail.orderId));state.checkoutDone=result.order;ui.paymentOrderId=result.order.id;ui.page='checkout';render();}catch(error){ui.page=state.user?'account':'login';notice(error.message,true);}});
  window.addEventListener('salesync:checkout-fresh',()=>{state.checkoutDone=null;ui.paymentOrderId=null;});
  window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/reset-password?')){state.resetToken=new URLSearchParams(location.hash.split('?')[1]).get('token');ui.page='reset-password';render();}});
  window.addEventListener('salesync:restore-account',event=>{if(state.user?.role==='customer'&&['orders','profile','addresses','saved','notifications','support','seller'].includes(event.detail.tab))state.accountTab=event.detail.tab;});
  // Age the displayed reference without fetching or mutating shared shopping state.
  setInterval(()=>{for(const section of document.querySelectorAll('[data-pos-fresh-until]')){const deadline=Number(section.dataset.posFreshUntil);if(deadline>0&&Date.now()>=deadline){section.querySelector('[data-pos-stale]').hidden=false;section.querySelector('[data-pos-status] .pill').textContent='stale';for(const cell of section.querySelectorAll('[data-pos-item-status]'))if(cell.textContent==='reference only')cell.textContent='stale';}}},5000);
  window.salesyncShopping={state,api,loadAdmin,loadSeller};
  return {persist,loadCustomer,afterLogout,beforeLogout:()=>shoppingQueue,renderPage,orderCards,staffContent,openProduct,savedAddressSelect,loadSeller};
};
